import React from 'react';

interface BellIconProps {
  size?: number;
  className?: string;
}

const BellIcon: React.FC<BellIconProps> = ({ size = 26, className = '' }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
    style={{ overflow: 'visible', filter: 'drop-shadow(0px 3px 5px rgba(245, 158, 11, 0.35))' }}
  >
    <defs>
      <linearGradient id="bellGold" x1="2" y1="2" x2="22" y2="22" gradientUnits="userSpaceOnUse">
        <stop offset="0%" stopColor="#FCD34D" />    {/* Light Yellow */}
        <stop offset="50%" stopColor="#F59E0B" />   {/* Solid Gold */}
        <stop offset="100%" stopColor="#D97706" />  {/* Dark Amber */}
      </linearGradient>
    </defs>

    <path 
      d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9z" 
      fill="url(#bellGold)" 
    />
    <path 
      d="M13.73 21a2 2 0 0 1-3.46 0" 
      fill="url(#bellGold)" 
    />
  </svg>
);

export default BellIcon;
